class LockingTree:
    def __init__(self, parent: List[int]):
        self.parent = parent
        self.owner = [-1] * len(parent)

    def lock(self, num: int, user: int) -> bool:
        if self.owner[num] != -1:
            return False
        self.owner[num] = user
        return True

    def unlock(self, num: int, user: int) -> bool:
        if self.owner[num] != user:
            return False
        self.owner[num] = -1
        return True

    def upgrade(self, num: int, user: int) -> bool:
        x = num
        while x != -1:
            if self.owner[x] != -1:
                return False
            x = self.parent[x]
        victims = []
        for v in range(len(self.parent)):
            if v == num or self.owner[v] == -1:
                continue
            x = self.parent[v]
            while x != -1 and x != num:
                x = self.parent[x]
            if x == num:
                victims.append(v)
        if not victims:
            return False
        for v in victims:
            self.owner[v] = -1
        self.owner[num] = user
        return True

