class LockingTree:
    def __init__(self, parent: List[int]):
        self.parent = parent
        self.children = [[] for _ in parent]
        for i, p in enumerate(parent):
            if p != -1:
                self.children[p].append(i)
        self.owner = {}

    def lock(self, num: int, user: int) -> bool:
        if num in self.owner:
            return False
        self.owner[num] = user
        return True

    def unlock(self, num: int, user: int) -> bool:
        if self.owner.get(num, -1) != user:
            return False
        del self.owner[num]
        return True

    def upgrade(self, num: int, user: int) -> bool:
        x = num
        while x != -1:
            if x in self.owner:
                return False
            x = self.parent[x]
        stack, victims = [num], []
        while stack:
            cur = stack.pop()
            for ch in self.children[cur]:
                if ch in self.owner:
                    victims.append(ch)
                stack.append(ch)
        if not victims:
            return False
        for v in victims:
            del self.owner[v]
        self.owner[num] = user
        return True

