class LockingTree {
    private final int[] par, owner;
    private final List<List<Integer>> kids;

    public LockingTree(int[] parent) {
        par = parent;
        owner = new int[parent.length];
        Arrays.fill(owner, -1);
        kids = new ArrayList<>();
        for (int i = 0; i < parent.length; i++) kids.add(new ArrayList<>());
        for (int i = 1; i < parent.length; i++) kids.get(par[i]).add(i);
    }

    public boolean lock(int num, int user) {
        if (owner[num] != -1) return false;
        owner[num] = user;
        return true;
    }

    public boolean unlock(int num, int user) {
        if (owner[num] != user) return false;
        owner[num] = -1;
        return true;
    }

    public boolean upgrade(int num, int user) {
        for (int x = num; x != -1; x = par[x])
            if (owner[x] != -1) return false;
        List<Integer> victims = new ArrayList<>();
        Deque<Integer> st = new ArrayDeque<>();
        st.push(num);
        while (!st.isEmpty()) {
            int cur = st.pop();
            for (int ch : kids.get(cur)) {
                if (owner[ch] != -1) victims.add(ch);
                st.push(ch);
            }
        }
        if (victims.isEmpty()) return false;
        for (int v : victims) owner[v] = -1;
        owner[num] = user;
        return true;
    }
}

